import re,json
txt=open('fit_final.txt').read().splitlines()
pred={}
for line in txt:
    if line.startswith('P') and ' = ' in line and ':' in line:
        pid=line.split(' = ')[0]
        rest=line.split(': ',1)[1]
        vals={}
        for m in re.finditer(r'(B2|B3|B4|B8|B11|B12|NDVI|NDWI) (-?\d+\.\d+)', rest):
            vals[m.group(1)]=float(m.group(2))
        if vals:
            pred[pid]=vals
rationale=("I used the standardized latent trajectory fit with inverse-variance band weighting and simplex weights, "
           "so all bands jointly determine a scale-preserving convex combination while reducing the influence of high-variance raw reflectance bands. "
           "A long matching window was allowed to capture the full seasonal transition leading into late September; the selected m=80 passed the R<=0.15 tolerance and kept two analogous historical seasonal continuations, dominated by the prior year with support from an earlier cycle. "
           "Predictions are the fitted convex combination of the observed forward values, avoiding extrapolating in standardized space.")
out={"prediction":pred,"rationale":rationale}
open('answer.json','w').write(json.dumps(out,indent=2))
print(open('answer.json').read()[:2000])
print("... periods",len(pred))
